query:
-- Tabacs orientaux
SELECT id, name, variety_type, origin_country, olfactive_profile, description FROM tabacs WHERE origin_country IN ('Turquie', 'Grèce', 'Bulgarie', 'Macédoine', 'Syrie') OR variety_type LIKE '%oriental%' OR name LIKE '%Samsun%' OR name LIKE '%Xanthi%' OR name LIKE '%Izmir%' OR name LIKE '%Basma%' OR name LIKE '%Latakia%' OR name LIKE '%Oriental%' LIMIT 15;

-- Vétiver
SELECT id, name, latin_name, origin, olfactive_profile FROM plants WHERE name LIKE '%vétiver%' OR name LIKE '%vetiver%' OR latin_name LIKE '%Chrysopogon%' OR latin_name LIKE '%Vetiveria%' LIMIT 10;

-- Cannabis landrace
SELECT id, name, latin_name, origin, olfactive_profile FROM plants WHERE name LIKE '%cannabis%' OR name LIKE '%landrace%' OR name LIKE '%sativa%' OR name LIKE '%indica%' LIMIT 10;

